DataSourceScript.Source:

import sailpoint.object.*;

Map map = new HashMap();
List fields = new ArrayList();
fields.add("count(*)");
fields.add("count(distinct parent.id)");
fields.add("count(distinct parent.certification.id)");
fields.add("count(distinct parent.certification.certificationGroups.id)");
Iterator it = context.search(CertificationItem.class, new QueryOptions(baseQueryOptions), fields);
if (it.hasNext()) {
  Object[] r = (Object[]) it.next();
  map.put("items", r[0]);
  map.put("identities", r[1]);
  map.put("certifications", r[2]);
  map.put("campaigns", r[3]);
}

QueryOptions subs = new QueryOptions(baseQueryOptions);
subs.addFilter(Filter.notnull("parent.certification.parent"));
it = context.search(CertificationItem.class, subs, "count(distinct parent.certification.id)");
map.put("subCertifications", it.hasNext() ? ((Object[]) it.next())[0] : null);

QueryOptions decided = new QueryOptions(baseQueryOptions);
decided.addFilter(Filter.notnull("action.status"));
map.put("decided", context.countObjects(CertificationItem.class, decided));

return map;

QueryScript.Source:
import sailpoint.object.*;

if (value != null && !value.isEmpty()) {
  List types = new ArrayList();
  for (Object v : value) {
    types.add(Enum.valueOf(Certification.Type.class, v.toString()));
  }
  queryOptions.addFilter(Filter.in("parent.certification.type", types));
}
return queryOptions;

import sailpoint.object.*;
import sailpoint.api.ObjectUtil;

// certifiers is a list of names; find the certifications first, then filter on their IDs.
if (value != null && !value.isEmpty()) {
  Set certIds = new HashSet();
  for (Object name : ObjectUtil.convertIdsToNames(context, Identity.class, value)) {
    QueryOptions qo = new QueryOptions();
    qo.addFilter(Filter.containsAll("certifiers", Arrays.asList(new Object[] { name })));
    Iterator it = context.search(Certification.class, qo, "id");
    while (it.hasNext()) {
      certIds.add(((Object[]) it.next())[0]);
    }
  }
  if (certIds.isEmpty()) {
    certIds.add("none");
  }
  queryOptions.addFilter(Filter.in("parent.certification.id", new ArrayList(certIds)));
}
return queryOptions;

ValueScript.Source:
import sailpoint.object.*;
import sailpoint.api.ObjectUtil;

return (value != null) ? ObjectUtil.convertIdsToNames(context, Identity.class, value) : null;

QueryScript.Source:
import sailpoint.object.*;
import sailpoint.api.ObjectUtil;

if (value != null && !value.isEmpty()) {
  List filters = new ArrayList();
  for (Object app : ObjectUtil.convertIdsToNames(context, Application.class, value)) {
    filters.add(Filter.containsAll("applicationNames", Arrays.asList(new Object[] { app })));
  }
  queryOptions.addFilter(Filter.or(filters));
}
return queryOptions;

import sailpoint.object.*;

if ("Open".equals(value)) {
  queryOptions.addFilter(Filter.isnull("parent.certification.signed"));
} else if ("Signed".equals(value)) {
  queryOptions.addFilter(Filter.notnull("parent.certification.signed"));
}
return queryOptions;

import sailpoint.object.*;

if ("Top level only".equals(value)) {
  queryOptions.addFilter(Filter.isnull("parent.certification.parent"));
} else if ("Sub-certifications only".equals(value)) {
  queryOptions.addFilter(Filter.notnull("parent.certification.parent"));
}
return queryOptions;

import sailpoint.object.*;

if (value != null && !value.isEmpty()) {
  Map statuses = new HashMap();
  statuses.put("Approved", new String[] { "Approved", "ApproveAccount" });
  statuses.put("Revoked", new String[] { "Remediated", "RevokeAccount" });
  statuses.put("Allowed", new String[] { "Mitigated" });
  statuses.put("Acknowledged", new String[] { "Acknowledged" });
  statuses.put("Reassigned", new String[] { "AccountReassign" });

  List filters = new ArrayList();
  List picked = new ArrayList();
  for (Object v : value) {
    if ("Open".equals(v)) {
      filters.add(Filter.isnull("action"));
    } else if (statuses.containsKey(v)) {
      for (String s : (String[]) statuses.get(v)) {
        picked.add(Enum.valueOf(CertificationAction.Status.class, s));
      }
    }
  }
  if (!picked.isEmpty()) {
    filters.add(Filter.in("action.status", picked));
  }
  if (!filters.isEmpty()) {
    queryOptions.addFilter(filters.size() == 1 ? (Filter) filters.get(0) : Filter.or(filters));
  }
}
return queryOptions;

RenderScript.Source:
import sailpoint.object.*;

Certification cert = (value == null) ? null : context.getObjectById(Certification.class, value);
if (cert == null || cert.getCertifiers() == null) return null;
List names = new ArrayList();
for (String name : cert.getCertifiers()) {
  QueryOptions qo = new QueryOptions();
  qo.addFilter(Filter.eq("name", name));
  Iterator it = context.search(Identity.class, qo, "displayName");
  Object dn = it.hasNext() ? ((Object[]) it.next())[0] : null;
  sailpoint.tools.Util.flushIterator(it);
  names.add((dn == null) ? name : dn + " (" + name + ")");
}
return sailpoint.tools.Util.listToCsv(names);

import sailpoint.object.*;

Certification cert = (value == null) ? null : context.getObjectById(Certification.class, value);
if (cert == null || cert.getSignOffHistory() == null) return null;
List names = new ArrayList();
for (SignOffHistory h : cert.getSignOffHistory()) {
  String name = h.getSignerDisplayableName();
  if (name != null && !names.contains(name)) names.add(name);
}
return sailpoint.tools.Util.listToCsv(names);

String first = (String) scriptArgs.get("parent.firstname");
String last = (String) scriptArgs.get("parent.lastname");
if (first != null || last != null) {
  return ((first == null ? "" : first) + " " + (last == null ? "" : last)).trim();
}
String[] keys = { "parent.identity", "parent.targetDisplayName", "parent.targetName", "parent.accountGroup" };
for (String k : keys) {
  Object v = scriptArgs.get(k);
  if (v != null) return v;
}
return null;

if (value == null) return null;
Map labels = new HashMap();
labels.put("Bundle", "Role");
labels.put("Exception", "Entitlement");
labels.put("Account", "Account");
labels.put("PolicyViolation", "Policy violation");
labels.put("AccountGroupMembership", "Group membership");
labels.put("DataOwner", "Entitlement (owner review)");
String s = value.toString();
return labels.containsKey(s) ? labels.get(s) : s;

import sailpoint.object.*;

Object attr = scriptArgs.get("exceptionAttributeName");
Object val = scriptArgs.get("exceptionAttributeValue");
if (value == null || attr == null || val == null) return null;
QueryOptions qo = new QueryOptions();
qo.addFilter(Filter.eq("application.name", value));
qo.addFilter(Filter.eq("attribute", attr));
qo.addFilter(Filter.eq("value", val));
Iterator it = context.search(ManagedAttribute.class, qo, "displayName");
Object dn = it.hasNext() ? ((Object[]) it.next())[0] : null;
sailpoint.tools.Util.flushIterator(it);
return (dn == null) ? val : dn;

import sailpoint.reporting.ReportingLibrary;
Object d = ReportingLibrary.describeCertificationEntitlement(value, scriptArgs.get("bundle"), scriptArgs.get("violationSummary"), null);
return (d == null) ? scriptArgs.get("targetDisplayName") : d;

if (value == null) return "Open";
Map labels = new HashMap();
labels.put("Approved", "Approved");
labels.put("ApproveAccount", "Approved (account)");
labels.put("Remediated", "Revoked");
labels.put("RevokeAccount", "Revoked (account)");
labels.put("Mitigated", "Allowed (exception)");
labels.put("Acknowledged", "Acknowledged");
labels.put("AccountReassign", "Reassigned");
labels.put("Delegated", "Delegated");
labels.put("Cleared", "Cleared");
labels.put("Modified", "Modified");
String s = value.toString();
return labels.containsKey(s) ? labels.get(s) : s;
